statuses=['NOT_EVALUATED_PROVISIONAL','NOT_EVALUATED_FIXED_WINDOW','DISABLED','NOT_APPLICABLE','FIRED','NOT_FIRED']
statusText={'en':'Not evaluated (provisional)|Not evaluated (fixed window)|Disabled|Not applicable|Triggered|Not triggered',
'fr':'Non évaluée (provisoire)|Non évaluée (fenêtre fixe)|Désactivée|Non applicable|Déclenchée|Non déclenchée',
'pt':'Não avaliada (provisório)|Não avaliada (janela fixa)|Desativada|Não aplicável|Acionada|Não acionada',
'es':'No evaluada (provisional)|No evaluada (ventana fija)|Desactivada|No aplicable|Activada|No activada'}
