policy={'en':('Review','Minimum control-chart baseline points'),'fr':('Revue','Nombre minimal de points pour les cartes de contrôle'),'pt':('Revisão','Mínimo de pontos de base para cartas de controlo'),'es':('Revisión','Mínimo de puntos de referencia para gráficos de control'),'es-419':('Revisión','Mínimo de puntos de referencia para gráficos de control')}
for locale,text in texts.items():
 values=text.split('|');assert len(values)==len(keys)
 for folder in ['client/src/translations','server/locales']:
  file=root/folder/(locale+'.json');data=json.loads(file.read_bytes())
  assert 'controlCharts' not in data
  data['controlCharts']=dict(zip(keys,values));data['controlCharts']['ruleStatus']=dict(zip(statuses,statusText[locale].split('|')))
  data['policies']['review']=policy[locale][0];data['policies']['keys']['qc_controlChartMinPoints']=policy[locale][1]
  file.write_bytes((json.dumps(data,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))
print('Five client and server locales populated; existing translations preserved.')
